# ── Группировка по темам ─────────────────────────────────────────────
TOPICS = {}
for g in GESTURES:
    topic = g["topic"]
    if topic not in TOPICS:
        TOPICS[topic] = {"name": topic, "gesture_ids": [], "count": 0}
    TOPICS[topic]["gesture_ids"].append(g["id"])
    TOPICS[topic]["count"] += 1


def get_gestures(topic: str = None, difficulty: int = None, search: str = ""):
    """Фильтрация жестов по теме, сложности и поиску."""
    result = GESTURES
    if topic:
        result = [g for g in result if g["topic"] == topic]
    if difficulty:
        result = [g for g in result if g["difficulty"] == difficulty]
    if search:
        q = search.lower()
        result = [g for g in result if q in g["name"].lower() or q in g["ru"].lower()]
    return result


def get_gesture_by_id(gid: int):
    """Получение одного жеста по ID."""
    for g in GESTURES:
        if g["id"] == gid:
            return g
    return None


def get_topics():
    """Список всех тем с количеством жестов."""
    return [
        {"name": t["name"], "count": t["count"]}
        for t in sorted(TOPICS.values(), key=lambda x: x["name"])
    ]
